          { type: 'email', email: 'john@example.com', field: { id: 'f2', type: 'email', ref: 'email' } },
          { type: 'text', text: 'Acme Inc', field: { id: 'f3', type: 'short_text', ref: 'company' } },
          { type: 'phone', phone: '+15551234567', field: { id: 'f4', type: 'phone', ref: 'phone' } },
