    expect(calls[0].json).toEqual({ name: 'Acme Inc' })
    expect(calls[1].json).toEqual({
      name: 'John Doe',
      email: [{ value: 'john@example.com', primary: true }],
      phone: [{ value: '+15551234567', primary: true }],
